import 'package:flutter/material.dart';import 'package:flutter_svg/flutter_svg.dart';import '../../../../Config/Assets/image_svg.dart';import '../../../../Core/Resources/app_fonts.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';class CartScreen extends StatelessWidget {  const CartScreen({super.key});  @override  Widget build(BuildContext context) {    final local = context.local;    return Scaffold(      appBar: AppBar(        title: Text(          local.cart,          style: AppTextStyles.h6Bold,        ),        centerTitle: true,      ),      body: Center(          child: Column(        mainAxisAlignment: MainAxisAlignment.center,        children: [          SvgPicture.asset(AppImagesSvg.cartEmpty),          Text(            local.massageInCart,            style: AppTextStyles.bodyMediumBold,          )        ],      )),    );  }}